export class UriError extends Error {}

export function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/s.exec(s)
  const r = { scheme: m[1], authority: m[2], path: m[3], query: m[4], fragment: m[5] }
  if (r.authority !== undefined) {
    let a = r.authority
    const at = a.lastIndexOf('@')
    if (at >= 0) { r.userinfo = a.slice(0, at); a = a.slice(at + 1) }
    const rb = a.lastIndexOf(']')
    const c = a.indexOf(':', rb + 1)
    if (c >= 0) { r.port = a.slice(c + 1); a = a.slice(0, c) }
    r.host = a
  }
  return r
}

export function check(r) {
  const parts = [['path', r.path], ['userinfo', r.userinfo], ['host', r.host], ['query', r.query], ['fragment', r.fragment]]
  for (const [name, v] of parts) {
    if (v !== undefined && /%(?![0-9A-Fa-f]{2})/.test(v)) {
      throw new UriError(`the ${name} has a truncated percent-encoding`)
    }
  }
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

