import { UriError, parse, check, normalize, resolve, serialize } from './uri.js'

const mode = process.argv.length === 3 ? process.argv[2] : undefined
if (mode !== 'normalize' && mode !== 'resolve') {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

const out = []
try {
  lines.forEach((line, idx) => {
    try {
      if (mode === 'normalize') {
        const r = parse(line)
        check(r)
        out.push(serialize(normalize(r)))
      } else {
        const sp = line.indexOf(' ')
        if (sp < 0) throw new UriError('expected a base and a reference')
