        if (base.scheme === undefined) throw new UriError('the base has no scheme')
        const ref = parse(line.slice(sp + 1))
        check(base)
        check(ref)
        out.push(serialize(normalize(resolve(base, ref))))
      }
    } catch (e) {
      if (e instanceof UriError) throw new UriError(`line ${idx + 1}: ${e.message}`)
      throw e
    }
  })
} catch (e) {
  if (!(e instanceof UriError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
