    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })
}

export function removeDots(path) {
  let inp = path
  let out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, out.lastIndexOf('/') < 0 ? 0 : out.lastIndexOf('/'))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function serialize(r) {
  let s = ''
  if (r.scheme !== undefined) s += r.scheme + ':'
  if (r.host !== undefined) {
    s += '//'
    if (r.userinfo !== undefined) s += r.userinfo + '@'
    s += r.host
    if (r.port !== undefined) s += ':' + r.port
  }
  s += r.path
  if (r.query !== undefined) s += '?' + r.query
  if (r.fragment !== undefined) s += '#' + r.fragment
  return s
}

export function normalize(r) {
  const n = { ...r }
  if (n.scheme !== undefined) n.scheme = lower(n.scheme)
  n.path = pct(n.path)
  n.query = pct(n.query)
  n.fragment = pct(n.fragment)
  if (n.host !== undefined) {
    n.userinfo = pct(n.userinfo)
    n.host = pct(n.host).replace(/(%[0-9A-F]{2})|[A-Z]/g, (m, p) => (p ? m : m.toLowerCase()))
    if (n.port !== undefined && (n.port === '' || n.port === DEFAULT_PORT[n.scheme])) delete n.port
  }
  n.path = removeDots(n.path)
  if (n.host !== undefined && n.path === '') n.path = '/'
  return n
}

export function resolve(base, ref) {
  const t = {}
  if (ref.scheme !== undefined) {
    Object.assign(t, ref, { path: removeDots(ref.path) })
  } else if (ref.host !== undefined) {
    Object.assign(t, ref, { scheme: base.scheme, path: removeDots(ref.path) })
  } else {
    t.scheme = base.scheme
    t.host = base.host; t.userinfo = base.userinfo; t.port = base.port
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
      else {
        let merged
        if (base.host !== undefined && base.path === '') merged = '/' + ref.path
        else {
          const i = base.path.lastIndexOf('/')
          merged = base.path.slice(0, i + 1) + ref.path
        }
        t.path = removeDots(merged)
      }
      t.query = ref.query
    }
    t.fragment = ref.fragment
    if (t.host === undefined) { delete t.host; delete t.userinfo; delete t.port }
  }
  return t
}
